import React from "react";

const Cart = (cart, togleCart,  removeFromCart ) =>{
    return(
        <div>
        <div>
            <button>
                Закрыть
            </button>
            <h2>
                ваша карзина
            </h2>
            {cart.length === 0 ? (
                <p>
                    Карзина пуста
                </p>
            ): (
                <ul>
{cart.map((product) => (
    <li key={product.id}>
        <h3></h3>
    </li>
))}
                </ul>
            )}
        </div>
        </div>
    )
}
export default Cart
